------------------
---- MONITORS ----
------------------

-- See https://wiki.hypr.land/configuring/core/monitors/
local primary = "DP-3"
local secondary = "HDMI-A-1"

hl.monitor({
    output   = primary,
    mode     = "1920x1080@165",
    position = "0x0",
    scale    = "auto",
    supports_wide_color = -1
})

hl.monitor({
    output   = secondary,
    mode     = "preferred",
    position = "0x-1080",
    scale    = "auto",
})

-- Workspaces 1-5 live on the primary monitor, 6-10 on the secondary
for ws = 1, 5 do
    hl.workspace_rule({ workspace = tostring(ws), monitor = primary, default = true })
end

for ws = 6, 10 do
    hl.workspace_rule({ workspace = tostring(ws), monitor = secondary, default = true })
end
