---- KEYBINDINGS ----
---------------------

local mainMod = "SUPER" -- Sets "Windows" key as main modifier

-- Example binds, see https://wiki.hypr.land/configuring/core/binds/ for more
hl.bind(mainMod .. " + T", hl.dsp.exec_cmd(terminal))
local closeWindowBind = hl.bind(mainMod .. " + Q", hl.dsp.window.close())
-- closeWindowBind:set_enabled(false)
hl.bind(mainMod .. " + M", hl.dsp.exec_cmd("hyprshutdown"))
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + V", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + A", hl.dsp.exec_cmd(menu))
hl.bind(mainMod .. " + P", hl.dsp.window.pseudo())
hl.bind(mainMod .. " + J", hl.dsp.layout("togglesplit"))    -- dwindle only
hl.bind(mainMod .. " + C", hl.dsp.exec_cmd("google-chrome-stable"))
hl.bind(mainMod .. " + Backspace", hl.dsp.exec_cmd(" pkill wlogout || wlogout"))

hl.bind(mainMod .. " + L", hl.dsp.exec_cmd("loginctl lock-session"))

-- SwayNC bindings
hl.bind(mainMod .. " + N", hl.dsp.exec_cmd("swaync-client -t"))
hl.bind(mainMod .. " + SHIFT + N", hl.dsp.exec_cmd("swaync-client -d"))

-- Clipboard history and color picker
hl.bind(mainMod .. " + SHIFT + V", hl.dsp.exec_cmd("$HOME/.local/bin/rice-clipboard"))
hl.bind(mainMod .. " + SHIFT + C", hl.dsp.exec_cmd("hyprpicker -a"))

-- Night light (hyprsunset)
hl.bind(mainMod .. " + SHIFT + F10", hl.dsp.exec_cmd("$HOME/.local/bin/rice-nightlight"))

-- Wallpaper Manager
hl.bind("SUPER + F6", hl.dsp.exec_cmd("$HOME/.local/bin/wall next"))
hl.bind("SUPER + SHIFT + F6", hl.dsp.exec_cmd("$HOME/.local/bin/wall prev"))
hl.bind("SUPER + F7", hl.dsp.exec_cmd("$HOME/.local/bin/wall random"))
hl.bind("SUPER + F8", hl.dsp.exec_cmd("$HOME/.local/bin/wall pick"))

-- Screen Recorder
hl.bind("SUPER + F9", hl.dsp.exec_cmd("$HOME/.local/bin/gsr-toggle"))

-- Print = select region, then annotate
hl.bind("Print", hl.dsp.exec_cmd('mkdir -p ~/Pictures/Screenshots; f=/tmp/shot-$(date +%s).png; g=$(slurp) || exit; grim -g "$g" "$f" && wl-copy -t image/png < "$f" && [ "$(notify-send -i "$f" -A default="Open in Satty" "Screenshot copied" "Click to annotate")" = default ] && satty -f "$f" --copy-command wl-copy --early-exit -o "$HOME/Pictures/Screenshots/%Y%m%d_%H%M%S.png"'))

hl.bind("SHIFT + Print", hl.dsp.exec_cmd('mkdir -p ~/Pictures/Screenshots; f=$HOME/Pictures/Screenshots/$(date +%Y%m%d_%H%M%S).png; grim "$f" && wl-copy -t image/png < "$f" && [ "$(notify-send -i "$f" -A default="Open in Satty" "Screenshot saved" "$f")" = default ] && satty -f "$f" --copy-command wl-copy --early-exit -o "$HOME/Pictures/Screenshots/%Y%m%d_%H%M%S-edited.png"'))

hl.bind(mainMod .. " + Print", hl.dsp.exec_cmd('mkdir -p ~/Pictures/Screenshots; f=$HOME/Pictures/Screenshots/$(date +%Y%m%d_%H%M%S).png; g=$(slurp -o -r) || exit; grim -g "$g" "$f" && wl-copy -t image/png < "$f" && [ "$(notify-send -i "$f" -A default="Open in Satty" "Screenshot saved" "$f")" = default ] && satty -f "$f" --copy-command wl-copy --early-exit -o "$HOME/Pictures/Screenshots/%Y%m%d_%H%M%S-edited.png"'))

hl.bind("SUPER + SHIFT + Print", hl.dsp.exec_cmd([[mkdir -p ~/Pictures/Screenshots; f=$HOME/Pictures/Screenshots/$(date +%Y%m%d_%H%M%S).png; ws=$(hyprctl monitors -j | jq -c 'map(.activeWorkspace.id)'); g=$(hyprctl clients -j | jq -r --argjson ws "$ws" '.[] | select(.mapped and (.workspace.id as $w | $ws | index($w))) | "\(.at[0]),\(.at[1]) \(.size[0])x\(.size[1])"' | slurp -r) || exit; grim -g "$g" "$f" && wl-copy -t image/png < "$f" && [ "$(notify-send -i "$f" -A default="Open in Satty" "Screenshot saved" "$f")" = default ] && satty -f "$f" --copy-command wl-copy --early-exit -o "$HOME/Pictures/Screenshots/%Y%m%d_%H%M%S-edited.png"]]))

-- Move focus with mainMod + arrow keys
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }))

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]

for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key,             hl.dsp.focus({ workspace = i}))
    hl.bind(mainMod .. " + SHIFT + " .. key,     hl.dsp.window.move({ workspace = i }))
end

-- Example special workspace (scratchpad)
hl.bind(mainMod .. " + S",         hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.window.move({ workspace = "special:magic" }))

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Volume/brightness keys, with the SwayOSD overlay
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("swayosd-client --output-volume raise"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("swayosd-client --output-volume lower"), { locked = true, repeating = true })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("swayosd-client --output-volume mute-toggle"), { locked = true, repeating = true })
hl.bind("XF86AudioMicMute",     hl.dsp.exec_cmd("swayosd-client --input-volume mute-toggle"),  { locked = true, repeating = true })
hl.bind("XF86MonBrightnessUp",  hl.dsp.exec_cmd("$HOME/.local/bin/rice-brightness up"),        { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown",hl.dsp.exec_cmd("$HOME/.local/bin/rice-brightness down"),      { locked = true, repeating = true })

-- Requires playerctl
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl next"),       { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"),   { locked = true })


